#include <iostream>
#include <memory>
#include <utility>

#include <new>

bool indice_valido(int indice) {
    return indice == 0 || indice == 1;
}

class Ficha {
public:
    // Añade el constructor sin argumentos y las dos operaciones de movimiento.
    Ficha(const Ficha&) = delete;
    Ficha& operator=(const Ficha&) = delete;
    ~Ficha() = default;
    bool hay() const { return dato_ != nullptr; }
    int valor() const { return *dato_; }
    bool poner(int valor);
    bool cambiar(int valor);
    bool vaciar();
private:
    std::unique_ptr<int> dato_ = std::make_unique<int>(4);
};

bool Ficha::poner(int valor) {
    if (valor < 0 || valor > 9) {
        return false;
    }
    try {
        auto candidato = std::make_unique<int>(valor);
        dato_.swap(candidato);
        return true;
    } catch (const std::bad_alloc&) {
        return false;
    }
}

bool Ficha::cambiar(int valor) {
    if (!dato_ || valor < 0 || valor > 9) {
        return false;
    }
    *dato_ = valor;
    return true;
}

bool Ficha::vaciar() {
    dato_.reset();
    return true;
}

bool entregar(Ficha& origen, Ficha& destino) {
    if (&origen == &destino || !origen.hay()) {
        return false;
    }
    Ficha intermedia = std::move(origen);
    destino = std::move(intermedia);
    return true;
}

void mostrar_dato(bool hay, int valor) {
    if (hay) {
        std::cout << valor;
    } else {
        std::cout << 'X';
    }
}

void mostrar(const Ficha& primera, const Ficha& segunda) {
    mostrar_dato(primera.hay(), primera.hay() ? primera.valor() : 0);
    std::cout << ':';
    mostrar_dato(segunda.hay(), segunda.hay() ? segunda.valor() : 0);
}

int main() {
    int cantidad = 0;
    if (!(std::cin >> cantidad) || cantidad < 1 || cantidad > 12) {
        return 1;
    }
    Ficha primera;
    Ficha segunda;
    segunda.cambiar(7);
    std::cout << "Inicio:";
    mostrar(primera, segunda);
    std::cout << '\n';
    for (int i = 0; i < cantidad; ++i) {
        int operacion = 0;
        int a = 0;
        int b = 0;

        if (!(std::cin >> operacion >> a >> b)) {
            return 1;
        }
        const bool habia0 = primera.hay();
        const bool habia1 = segunda.hay();
        const int anterior0 = habia0 ? primera.valor() : 0;
        const int anterior1 = habia1 ? segunda.valor() : 0;
        bool aceptado = false;

        if (operacion == 1 && indice_valido(a) && indice_valido(b)) {
            Ficha& origen = a == 0 ? primera : segunda;
            Ficha& destino = b == 0 ? primera : segunda;
            aceptado = entregar(origen, destino);
        } else if (indice_valido(a)) {
            Ficha& ficha = a == 0 ? primera : segunda;
            if (operacion == 2) {
                aceptado = ficha.poner(b);
            } else if (operacion == 3) {
                aceptado = ficha.vaciar();
            } else if (operacion == 4) {
                aceptado = ficha.cambiar(b);
            }
        }
        std::cout << "Resultado:" << aceptado << ";Antes:";
        mostrar_dato(habia0, anterior0);
        std::cout << ':';
        mostrar_dato(habia1, anterior1);
        std::cout << ";Actual:";
        mostrar(primera, segunda);
        std::cout << '\n';
    }
    std::cout << "Final:";
    mostrar(primera, segunda);
    return 0;
}

